cd /work && wc -c workspace.dsl && node -e '
const fs = require("fs");
const dsl = fs.readFileSync("workspace.dsl", "utf8");
let h = 0;
for (let i = 0; i < dsl.length; i++) { h = (h * 31 + dsl.charCodeAt(i)) | 0; }
console.log("length:", dsl.length);
console.log("hash:", h);
' 2>/dev/null || python3 -c '
data = open("workspace.dsl", "rb").read().decode("utf-8")
h = 0
for ch in data:
    h = (h * 31 + ord(ch)) & 0xFFFFFFFF
    if h >= 1<<31: h -= 1<<32
    if h < 0: h += 1<<32
print("length:", len(data))
print("hash:", h)
'

